package gamestats.fixtures

import gamestats.codec.Codecs.given
import gamestats.model.*
import io.circe.parser.decode

import java.nio.file.{Files, Paths}
import scala.jdk.CollectionConverters.*

/** Matches from data/samples/demo-small.jsonl, generated by the simulator. Scenario matches
  * (`*-scn-*`) carry no injected problems, so their lines can be turned into a batch directly, as
  * the ingestor would send them.
  */
object Samples:
  private lazy val events: List[Event] =
    Files
      .readAllLines(Paths.get("../data/samples/demo-small.jsonl"))
      .asScala
      .toList
      .flatMap(line => decode[Event](line).toOption)

  def scenario(matchId: String): MatchBatch =
    val evs = events.filter(_.matchId == matchId).sortBy(_.seq)
    require(evs.nonEmpty, s"no events for $matchId")
    val players = evs.flatMap(_.playerId).distinct.sorted
    MatchBatch(
      batchId = s"b-$matchId",
      matchId = matchId,
      gameId = evs.head.gameId,
      gameVersion = "1.0",
      status = BatchStatus.COMPLETE,
      startedAt = evs.head.timestamp,
      finishedAt = Some(evs.last.timestamp),
      players = players,
      eventCount = evs.size,
      sentAt = evs.last.timestamp,
      events = evs
    )
